CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_senha_finalizar`(
    IN p_id_sessao_usuario BIGINT,
    IN p_id_senha BIGINT
)
    SQL SECURITY INVOKER
BEGIN

    CALL sp_sessao_assert(p_id_sessao_usuario);

    UPDATE senha
    SET status = 'FINALIZADA',
        finalizada_em = NOW(6)
    WHERE id = p_id_senha;

END ;;
